import {DEFAULTS,PRESETS,validateSettings} from '../core/settings.js';
import {elevation,elevationSI,isImperial,unitLabels,temperatureDelta} from './units.js';
export const $=id=>document.getElementById(id);
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showToast(message,error=false){clearTimeout(showToast.timer);const el=$('toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;showToast.timer=setTimeout(()=>el.hidden=true,error?9000:4000);}
const ELEVATION_FIELDS={minElevation:[-12000,-100],maxElevation:[100,12000],plainsElevation:[0,1500],highlandUplift:[0,6000]};
function writeElevation(el,value){el.dataset.si=String(value);el.value=isImperial()?String(Math.round(elevation(value))):String(value);el.dataset.display=el.value;const limits=ELEVATION_FIELDS[el.name];el.min=String(elevation(limits[0]));el.max=String(elevation(limits[1]));el.step='any';}
function readElevation(el,unit){return el.value===el.dataset.display?Number(el.dataset.si):elevationSI(Number(el.value),unit);}
export function setForm(settings){for(const [key,value]of Object.entries(settings)){const el=$('settings-form').elements.namedItem(key);if(el){if(ELEVATION_FIELDS[key])writeElevation(el,value);else el.value=value;}}updateOutputs();}
export function readForm(){const out={};for(const [k,v]of new FormData($('settings-form')))out[k]=ELEVATION_FIELDS[k]?readElevation($('settings-form').elements.namedItem(k)):['seed','style','landformProfile','mountainStyle'].includes(k)?v:Number(v);return validateSettings(out);}
export function updateOutputs(){for(const output of document.querySelectorAll('output[data-for]')){const key=output.dataset.for,v=Number($('settings-form').elements.namedItem(key).value);output.value=key==='temperatureOffset'?`${v>0?'+':''}${temperatureDelta(v).toFixed(1)} ${unitLabels().temperature}`:key==='axialTilt'?`${v.toFixed(1)}°`:key==='wetness'?`${v.toFixed(2)}×`:`${Math.round(v*100)}%`;}for(const el of document.querySelectorAll('[data-elevation-unit]'))el.textContent=unitLabels().elevation;}
if(typeof window!=='undefined')window.addEventListener('atlas-units-changed',({detail})=>{for(const key of Object.keys(ELEVATION_FIELDS)){const el=$('settings-form').elements.namedItem(key);if(el)writeElevation(el,readElevation(el,detail.previous));}updateOutputs();});
export function initControls(onChange){$('preset').replaceChildren(...Object.keys(PRESETS).map(name=>new Option(name,name)));setForm(DEFAULTS);$('settings-form').addEventListener('submit',e=>e.preventDefault());$('settings-form').addEventListener('input',()=>{updateOutputs();onChange();});$('preset').addEventListener('change',()=>{const seed=$('seed').value;setForm({...DEFAULTS,...PRESETS[$('preset').value],seed});onChange();});$('randomize').onclick=()=>{$('seed').value=`${['Pelagic','Laurent','Meridian','Boreal','Thalassa','Caldera'][crypto.getRandomValues(new Uint32Array(1))[0]%6]}-${crypto.getRandomValues(new Uint32Array(1))[0].toString(36)}`;onChange();};$('reset-settings').onclick=()=>{setForm(DEFAULTS);$('preset').value='Earth-like';onChange();};}
export function tab(name){for(const key of ['inspect','statistics','civilization']){const button=$(`tab-${key}`),panel=$(`${key}-panel`);if(!button||!panel)continue;button.classList.toggle('active',name===key);button.setAttribute('aria-selected',name===key);panel.hidden=name!==key;}}
